// Parse incoming WhatsApp message from Meta Cloud API
const body = $input.first().json.body || $input.first().json;

const entry = body?.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;

// Handle verification challenge
if ($input.first().json.query?.['hub.challenge']) {
  return [{ json: { type: 'verification', challenge: $input.first().json.query['hub.challenge'] } }];
}

const message = value?.messages?.[0];
const contact = value?.contacts?.[0];

if (!message) {
  return [{ json: { type: 'no_message' } }];
}

return [{
  json: {
    type: 'message',
    phone: message.from,
    name: contact?.profile?.name || 'User',
    message_id: message.id,
    text: message?.text?.body || message?.interactive?.button_reply?.title || '',
    message_type: message.type,
    timestamp: message.timestamp,
    phone_number_id: value?.metadata?.phone_number_id
  }
}];

const phone = $('Parse WhatsApp Message').first().json.phone;
const name = $('Parse WhatsApp Message').first().json.name;
const userMessage = $('Parse WhatsApp Message').first().json.text;
const rawHistory = $input.first().json.value;

let history = [];
try {
  history = JSON.parse(rawHistory || '[]');
} catch(e) {
  history = [];
}

// Add new user message
history.push({ role: 'user', content: userMessage });

// Keep last 10 messages only
if (history.length > 10) history = history.slice(-10);

return [{
  json: {
    phone,
    name,
    userMessage,
    history,
    historyJson: JSON.stringify(history)
  }
}];

const aiResponse = $input.first().json.content?.[0]?.text || $input.first().json.text || '';
const phone = $('Build Conversation Context').first().json.phone;
const history = $('Build Conversation Context').first().json.history;

// Check if AI wants to book an appointment
const bookMatch = aiResponse.match(/BOOK_APPOINTMENT:(\{[^}]+\})/s);
const shouldBook = !!bookMatch;
let bookingData = null;
if (bookMatch) {
  try { bookingData = JSON.parse(bookMatch[1]); } catch(e) {}
}

// Clean response (remove the BOOK_APPOINTMENT line from user-facing message)
const cleanResponse = aiResponse.replace(/BOOK_APPOINTMENT:\{[^}]+\}/s, '').trim();

// Update history with assistant reply
history.push({ role: 'assistant', content: cleanResponse || aiResponse });

return [{
  json: {
    phone,
    response: cleanResponse || aiResponse,
    fullHistory: JSON.stringify(history),
    shouldBook,
    bookingData,
    phone_number_id: $('Parse WhatsApp Message').first().json.phone_number_id
  }
}];
